<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Support\{Access,Amount};
use App\Services\DocumentService;
class BusinessController {
 public function bootstrap(Request $r){$u=$r->user();Access::require($u,'view');
  $biz=DB::table('business')->first();$biz->modules=json_decode($biz->modules,true);
  $tables=[];foreach(['branches','warehouses','products','parties','accounts','prices'] as $t){$q=DB::table($t);if($t==='branches'&&$u->role!=='admin')$q->whereIn('id',$u->branch_ids??[]);if($t==='warehouses')Access::scope($q,$u);$tables[$t]=$q->orderBy('id')->limit(10000)->get();}
  $tables['employees']=$u->canDo('payroll')?Access::scope(DB::table('employees'),$u)->get():[];
  return ['user'=>$u,'business'=>$biz,'masters'=>$tables];
 }
 public function documents(Request $r){Access::require($r->user(),'view');$q=Access::scope(DB::table('documents'),$r->user());if(!$r->user()->canDo('costs'))$q->whereNotIn('kind',['purchase','purchase_return','purchase_order','goods_receipt','production']);if(!$r->user()->canDo('accounting'))$q->whereNotIn('kind',['journal','opening','opening_stock','payroll','depreciation']);if($r->filled('kind'))$q->where('kind',$r->input('kind'));if($r->filled('search'))$q->where('number','like','%'.$r->input('search').'%');return $q->orderByDesc('id')->paginate(50);}
 public function document(Request $r,int $id,DocumentService $svc){$d=DB::table('documents')->find($id);abort_unless($d,404);Access::require($r->user(),'view');Access::branch($r->user(),$d->branch_id);$this->sensitive($r,$d);return $svc->snapshot($id);}
 private function sensitive(Request $r,$d){if(in_array($d->kind,['purchase','purchase_return','purchase_order','goods_receipt','production']))Access::require($r->user(),'costs');if(in_array($d->kind,['journal','opening','opening_stock','payroll','depreciation']))Access::require($r->user(),'accounting');}
 public function save(Request $r,DocumentService $svc,?int $id=null){return ['id'=>$svc->save($r->all(),$r->user(),$id)];}
 public function post(Request $r,int $id,DocumentService $svc){$d=DB::table('documents')->find($id);abort_unless($d,404);$this->sensitive($r,$d);$svc->post($id,$r->user());return ['ok'=>true];}
 public function reverse(Request $r,int $id,DocumentService $svc){$v=$r->validate(['reason'=>'required|string|min:5|max:1000','date'=>'required|date_format:Y-m-d']);return ['id'=>$svc->reverse($id,$r->user(),$v['reason'],$v['date'])];}
 public function stock(Request $r){Access::require($r->user(),'view');$q=DB::table('stock_balances as s')->join('warehouses as w','s.warehouse_id','=','w.id')->join('products as p','p.id','=','s.product_id');Access::scope($q,$r->user(),'w.branch_id');$fields=['s.id','p.sku','p.name','p.unit','s.product_id','s.warehouse_id','w.name as warehouse','s.lot','s.expiry','s.quantity_milli','p.reorder_milli'];if($r->user()->canDo('costs'))$fields[]='s.value_paise';return $q->select($fields)->orderBy('p.name')->paginate(100);}
 public function dashboard(Request $r){$u=$r->user();Access::require($u,'view');$q=Access::scope(DB::table('documents'),$u)->where('status','posted');$sales=(clone $q)->where('kind','sale')->where('date',now()->toDateString())->sum('net_paise');$purchase=$u->canDo('costs')?(clone $q)->where('kind','purchase')->where('date',now()->toDateString())->sum('net_paise'):null;
  $ledger=Access::scope(DB::table('ledger_entries as l')->join('accounts as a','a.id','=','l.account_id'),$u,'l.branch_id');
  $balances=[];foreach(['1000','1010','1100','2000'] as $code)$balances[$code]=$u->canDo('accounting')?(clone $ledger)->where('a.code',$code)->selectRaw('COALESCE(SUM(l.debit_paise-l.credit_paise),0) as balance')->value('balance'):null;
  $stock=Access::scope(DB::table('stock_balances as s')->join('warehouses as w','w.id','=','s.warehouse_id'),$u,'w.branch_id');
  return ['sales_today'=>$sales,'purchases_today'=>$purchase,'balances'=>$balances,'negative_stock'=>(clone $stock)->where('quantity_milli','<',0)->count(),'drafts'=>Access::scope(DB::table('documents'),$u)->where('status','draft')->count(),'recent'=>Access::scope(DB::table('documents'),$u)->whereIn('kind',['sale','receipt','quote'])->orderByDesc('id')->limit(8)->get()];
 }
 public function report(Request $r){$u=$r->user();Access::require($u,'accounting');$v=$r->validate(['from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d','party_id'=>'nullable|integer','account_id'=>'nullable|integer']);$q=Access::scope(DB::table('ledger_entries as l')->join('accounts as a','a.id','=','l.account_id'),$u,'l.branch_id');if(!empty($v['from']))$q->where('l.date','>=',$v['from']);if(!empty($v['to']))$q->where('l.date','<=',$v['to']);if(!empty($v['party_id']))$q->where('l.party_id',$v['party_id']);if(!empty($v['account_id']))$q->where('l.account_id',$v['account_id']);
  $trial=(clone $q)->select('a.code','a.name','a.type')->selectRaw('SUM(l.debit_paise) as debit, SUM(l.credit_paise) as credit')->groupBy('a.code','a.name','a.type')->orderBy('a.code')->get();$profit=0;foreach($trial as $a)if(in_array($a->type,['income','expense']))$profit+=$a->credit-$a->debit;
  return ['trial'=>$trial,'profit_paise'=>$profit,'entries'=>(clone $q)->select('l.*','a.code','a.name')->orderByDesc('l.id')->limit(500)->get(),'entry_limit'=>500];
 }
 public function audit(Request $r){Access::require($r->user(),'audit');$q=DB::table('audit_events');if($r->user()->role!=='admin')$q->whereIn('branch_id',$r->user()->branch_ids??[]);if($r->filled('entity_id'))$q->where('entity_id',$r->integer('entity_id'))->where('entity_type',$r->input('entity_type','documents'));return $q->orderByDesc('id')->paginate(50);}
 public function print(Request $r,int $id,DocumentService $svc){$data=$this->document($r,$id,$svc);$d=(object)$data['document'];abort_unless(in_array($d->status,['posted','reversed']),422,'Post the document before printing.');$biz=json_decode($d->business_snapshot)??DB::table('business')->first();$party=json_decode($d->party_snapshot);$width=max(48,min(110,$r->integer('width',$biz->receipt_width??80)));return view('print',['d'=>$d,'lines'=>$data['lines'],'biz'=>$biz,'party'=>$party,'width'=>$width,'thermal'=>$r->input('format')==='thermal','money'=>fn($v)=>Amount::display((int)$v)]);}
 public function checkout(Request $r,int $id,DocumentService $svc){
  Access::require($r->user(),'approve');$v=$r->validate(['cash_account'=>'required|in:1000,1010']);return DB::transaction(function()use($r,$id,$svc,$v){DB::table('business')->lockForUpdate()->first();$d=DB::table('documents')->lockForUpdate()->find($id);abort_unless($d&&$d->kind==='sale',422,'Counter checkout requires a sales invoice.');Access::branch($r->user(),$d->branch_id);$svc->post($id,$r->user());$paid=DB::table('allocations')->where('invoice_id',$id)->sum('amount_paise');$returns=DB::table('documents')->where('related_id',$id)->where('kind','sale_return')->where('status','posted')->sum('total_paise');$balance=$d->total_paise-$paid-$returns;if($balance<=0)return ['id'=>$id,'already_paid'=>true];$receipt=$svc->save(['kind'=>'receipt','date'=>$d->date,'branch_id'=>$d->branch_id,'party_id'=>$d->party_id,'tax_treatment'=>'non_gst','reason'=>'Payment for '.$d->id,'state_code'=>$d->state_code,'price_tier'=>'retail','data'=>['cash_account'=>$v['cash_account'],'allocations'=>[['invoice_id'=>$id,'amount'=>number_format($balance/100,2,'.','')]]],'lines'=>[['account_id'=>DB::table('accounts')->where('code',$v['cash_account'])->value('id'),'description'=>'Counter sale receipt','quantity'=>'1','price'=>number_format($balance/100,2,'.','')]]],$r->user());$svc->post($receipt,$r->user());return ['id'=>$id,'receipt_id'=>$receipt];},3);
 }
 public function export(Request $r){Access::require($r->user(),'export');Access::require($r->user(),'accounting');$q=Access::scope(DB::table('ledger_entries as l')->join('accounts as a','a.id','=','l.account_id'),$r->user(),'l.branch_id')->select('l.date','l.document_id','a.code','a.name','l.debit_paise','l.credit_paise');return response()->streamDownload(function()use($q){$out=fopen('php://output','w');fputcsv($out,['Date','Document ID','Account code','Account','Debit INR','Credit INR']);foreach($q->orderBy('l.id')->cursor() as $e){$name=preg_match('/^[=+@\-\t\r]/',$e->name)?"'".$e->name:$e->name;fputcsv($out,[$e->date,$e->document_id,$e->code,$name,number_format($e->debit_paise/100,2,'.',''),number_format($e->credit_paise/100,2,'.','')]);}fclose($out);},'ledger.csv',['Content-Type'=>'text/csv']);}
}
